def is_solvable(words: list[str], result: str) -> bool:
    if max(len(w) for w in words) > len(result):
        return False  # a longer addend already exceeds the result
    weight, low_col, leading = {}, {}, set()
    for word, sign in [(w, 1) for w in words] + [(result, -1)]:
        if len(word) > 1:
            leading.add(word[0])
        for p, ch in enumerate(reversed(word)):
            weight[ch] = weight.get(ch, 0) + sign * 10**p
            low_col[ch] = min(low_col.get(ch, p), p)
    letters = sorted(weight, key=lambda ch: low_col[ch])
    # check_mod[i]: after assigning letters[:i+1], the partial sum must be a
    # multiple of this, because every later letter only touches higher columns
    check_mod = []
    for i, ch in enumerate(letters):
        nxt = low_col[letters[i + 1]] if i + 1 < len(letters) else None
        check_mod.append(10 ** (low_col[ch] + 1) if nxt != low_col[ch] else 1)
    used = [False] * 10

    def search(i, total):
        if i == len(letters):
            return total == 0
        ch = letters[i]
        w, mod = weight[ch], check_mod[i]
        for d in range(1 if ch in leading else 0, 10):
            if used[d]:
                continue
            t = total + w * d
            if t % mod:
                continue
            used[d] = True
            if search(i + 1, t):
                return True
            used[d] = False
        return False

    return search(0, 0)

