def maximum_invitations(favorite: List[int]) -> int:
    n = len(favorite)
    indeg = [0] * n
    for f in favorite:
        indeg[f] += 1
    # depth[v]: longest chain of admirers ending at v, counting v itself
    depth = [1] * n
