    while queue:
        u = queue.popleft()
        v = favorite[u]
        depth[v] = max(depth[v], depth[u] + 1)
        indeg[v] -= 1
        if indeg[v] == 0:
            queue.append(v)

    longest_cycle = 0
    pair_total = 0
    for i in range(n):
        if indeg[i] == 0:
            continue            # not on a cycle, or cycle already measured
        length, j = 0, i
        while indeg[j] > 0:
            indeg[j] = 0        # mark visited
            length += 1
            j = favorite[j]
        if length == 2:
            pair_total += depth[i] + depth[favorite[i]]
        else:
            longest_cycle = max(longest_cycle, length)
    return max(longest_cycle, pair_total)

