def recover_from_preorder(traversal: str) -> Optional[TreeNode]:
    path = []                       # path[i] is the latest node at depth i
    i, n = 0, len(traversal)
    while i < n:
        depth = 0
        while traversal[i] == "-":
            depth += 1
            i += 1
        start = i
        while i < n and traversal[i] != "-":
            i += 1
        node = TreeNode(int(traversal[start:i]))
        del path[depth:]            # climb back to the parent level
        if path:
