def count_partitions(nums: list[int], k: int) -> int:
    MOD = 10**9 + 7
    if sum(nums) < 2 * k:
        return 0
    # dp[s] = number of subsets with sum exactly s, for s < k
    dp = [0] * k
    dp[0] = 1
    for x in nums:
        for s in range(k - 1, x - 1, -1):
            dp[s] = (dp[s] + dp[s - x]) % MOD
    small = sum(dp) % MOD
    # each small subset can be the first or the second group
    return (pow(2, len(nums), MOD) - 2 * small) % MOD

