def maximum_candies(candies: list[int], k: int) -> int:
    total = sum(candies)
    if total < k:
        return 0
    lo, hi = 1, min(max(candies), total // k)
    # invariant: lo is feasible; find the largest feasible amount
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if sum(c // mid for c in candies) >= k:
            lo = mid
        else:
            hi = mid - 1
    return lo

